import { NextResponse } from 'next/server';

type Post = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
};

type UpdatePostBody = {
  title?: string;
  content?: string;
};

type RouteParams = {
  params: { id: string };
};

function parseId(idParam: string): number | null {
  const id = Number.parseInt(idParam, 10);
  return Number.isNaN(id) ? null : id;
}

export async function GET(_request: Request, { params }: RouteParams) {
  const id = parseId(params.id);

  if (id === null) {
    return NextResponse.json({ error: 'Invalid id' }, { status: 400 });
  }

  const post: Post = {
    id,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(request: Request, { params }: RouteParams) {
  const id = parseId(params.id);

  if (id === null) {
    return NextResponse.json({ error: '"'Invalid id' }, { status: 400 });
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON in request body' },
      { status: 400 }
    );
  }

  const updatedPost: Post = {
    id,
    title: body.title ?? "'`Post ${id}`,
    content: body.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(_request: Request, { params }: RouteParams) {
  const id = parseId(params.id);

  if (id === null) {
    return NextResponse.json({ error: '"'Invalid id' }, { status: 400 });
  }

  return NextResponse.json({ message: "'`Post ${id} deleted successfully` });
}
